package com.example.lending.domain;

import java.util.List;
import java.util.Optional;
import java.util.UUID;

// 한 책의 예약 줄. waiting 은 앞 순서부터 소진되지 않은 예약 목록이다.
public class ReservationQueue {

    private final UUID bookId;
    private final List<Reservation> waiting;

    public ReservationQueue(UUID bookId, List<Reservation> waiting) {
        this.bookId = bookId;
        this.waiting = List.copyOf(waiting);
    }

    public void ensureNotReserved(UUID memberId) {
        if (waiting.stream().anyMatch(reservation -> reservation.isFor(memberId))) {
            throw new AlreadyReservedException(bookId, memberId);
        }
    }

    public void ensureCanBorrow(UUID memberId) {
        if (!waiting.isEmpty() && !waiting.get(0).isFor(memberId)) {
            throw new ReservedForOtherException(bookId);
        }
    }

    // 맨 앞 예약자가 빌린 경우에만 예약을 소진하고, 그 예약을 돌려준다.
    public Optional<Reservation> fulfillFor(UUID memberId) {
        if (waiting.isEmpty() || !waiting.get(0).isFor(memberId)) {
            return Optional.empty();
        }
        Reservation front = waiting.get(0);
        front.fulfill();
        return Optional.of(front);
    }

    public List<Reservation> waiting() {
        return waiting;
    }

    public int size() {
        return waiting.size();
    }
}

