import com.example.lending.application.port.out.LoadActiveReservationsPort;
import com.example.lending.application.port.out.SaveReservationPort;
import com.example.lending.domain.Reservation;
import org.springframework.stereotype.Component;

import java.util.List;
import java.util.UUID;

@Component
public class ReservationPersistenceAdapter implements LoadActiveReservationsPort, SaveReservationPort {

    private final ReservationJpaRepository reservationJpaRepository;
    private final ReservationMapper reservationMapper = new ReservationMapper();

    public ReservationPersistenceAdapter(ReservationJpaRepository reservationJpaRepository) {
        this.reservationJpaRepository = reservationJpaRepository;
    }

    @Override
    public List<Reservation> loadWaitingReservations(UUID bookId) {
        return reservationJpaRepository.findByBookIdAndFulfilledFalseOrderBySeqAsc(bookId).stream()
                .map(reservationMapper::toDomain)
                .toList();
    }

    // 새 예약은 insert, 기존 예약은 소진 여부만 갱신한다(seq 를 유지해야 줄 순서가 보존된다).
    @Override
    public void saveReservation(Reservation reservation) {
        ReservationJpaEntity entity = reservationJpaRepository.findByReservationId(reservation.getId())
                .orElseGet(() -> reservationMapper.toEntity(reservation));
        entity.setFulfilled(reservation.isFulfilled());
        reservationJpaRepository.save(entity);
    }
}

